package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: it starts DRAFT, is opened and then settled; a clerk settling one whose due is above
 * the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT,
 * OPEN or PENDING claim can be voided, and a steward may void a SETTLED one within 7 days of its settlement. Only a
 * DRAFT can be edited. VOID is final. Only OPEN, PENDING and
 * SETTLED claims count toward the totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim with this status is open: OPEN, or PENDING (handled like an open claim). */
    public boolean open() {
        return this == OPEN || this == PENDING;
    }
}
package net.officefloor.hq.app.claim;

/**
 * A change of a claim's status: the status it may start from, the status it ends in, and its audit event. PEND is
 * never asked for by name: it is what a clerk's settle becomes when the due is above the clerk limit. RESETTLE
 * freezes a SETTLED claim again at today's figure.
 */
public enum ClaimAction {
    OPEN("open", ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
    SETTLE("settle", ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
    PEND(null, ClaimStatus.PENDING, "CLAIM_PENDING", ClaimStatus.OPEN),
    APPROVE("approve", ClaimStatus.SETTLED, "CLAIM_APPROVED", ClaimStatus.PENDING),
    REJECT("reject", ClaimStatus.OPEN, "CLAIM_REJECTED", ClaimStatus.PENDING),
    VOID("void", ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING,
            ClaimStatus.SETTLED),
    RESETTLE("resettle", ClaimStatus.SETTLED, "CLAIM_RESETTLED", ClaimStatus.SETTLED);

    private final String path;
    private final ClaimStatus to;
    private final String event;
    private final ClaimStatus[] from;

    ClaimAction(String path, ClaimStatus to, String event, ClaimStatus... from) {
        this.path = path;
        this.to = to;
        this.event = event;
        this.from = from;
    }

    /** The action named in the path, or null. */
    public static ClaimAction of(String path) {
        for (ClaimAction action : values()) {
            if (action.path != null && action.path.equals(path)) {
                return action;
            }
        }
        return null;
    }

    public boolean allowedFrom(ClaimStatus status) {
        for (ClaimStatus s : from) {
            if (s == status) {
                return true;
            }
        }
        return false;
    }

    public ClaimStatus to() {
        return to;
    }

    public String event() {
        return event;
    }

    /** Whether the action fixes the claim's due: settling, approving a pending settle, or re-settling. */
    public boolean settles() {
        return to == ClaimStatus.SETTLED;
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
 * Opening gives the claim the sheet's next number; a voided claim keeps its number (it is never reused). While the
 * sheet's period numbering from date is set and its today is on or after it, opening instead gives the claim the next
 * number within the period containing its due-by (P1-1, P1-2, ...), or within the claims in no period (X-1, ...).
 * Opening, settling and voiding are refused (400) to a role the sheet's permission matrix does not allow them.
 * Opening records the user who opened it; that user cannot settle it (four eyes). Nor can the user who last edited
 * it (through its editor or its row's amount entry) settle or approve it. A deferred claim cannot be settled.
 * Settling fixes the claim's due at the greater of the sheet's floor in force on its date and its figure — at its person's grade's rate in force on the claim's date,
 * rounded by its policy date, or, when a statement bound the claim, the figure it was bound to — plus the late charge it has then, if overdue, frozen in; with no
 * figure it stays live. A clerk settling a claim whose due is above the sheet's clerk limit (a due of n/a is within any
 * limit) makes it PENDING instead, live and unfixed. A claim with no proofs whose due is above the proof threshold in force on its date —
 * its person's grade's own, when that grade has one then, else the sheet's — is refused settling or approving — before the clerk limit is considered, so it never goes PENDING.
 * A claim with an empty note whose due (as shown now) is above the sheet's note threshold in force on its date is refused opening. Only a steward approves a PENDING claim (fixing its due at its live
 * figure, plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
 * Only a steward voids a SETTLED claim, and only while the sheet's today is within 7 days of its settlement (the
 * status log's latest SETTLED date); it keeps its number and its frozen due, which leaves every total.
 * While the sheet's void reasons list is not empty, a void is refused (400) without a reason chosen from it; a reason
 * not on the list is always refused.
 */
public class ApplyClaimAction {

    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a SETTLED claim. */
    static final int VOID_SETTLED_DAYS = 7;

    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimActionRequest request, SheetRepository sheets,
            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
            VoidReasonRepository voidReasons, ClaimRepository claims, ClaimLogRepository logs, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
        ClaimAction found = ClaimAction.of(action);
        if (found == null) {
            throw new InvalidClaimException("No such claim action: " + action);
        }
        if (!found.allowedFrom(claim.status())) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
        }
        if ((found == ClaimAction.OPEN || found == ClaimAction.SETTLE || found == ClaimAction.VOID)
                && !settings.find(claim.sheetId()).may(user, action)) {
            throw new InvalidClaimException("The user's role is not allowed to " + action + " a claim.");
        }
        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
        }
        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
        }
        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE)
                && user.equals(claims.editedBy(claim.sheetId(), claim.id()))) {
            throw new InvalidClaimException("The user who last edited a claim cannot " + action + " it.");
        }
        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can " + action + " a pending claim.");
        }
        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
        }
        if (found == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
                throw new InvalidClaimException("Only a steward can void a settled claim.");
            }
            LocalDate settledOn = logs.find(claim.sheetId(), claim.id()).stream()
                    .filter((l) -> l.status() == ClaimStatus.SETTLED).map(ClaimLogLine::date)
                    .reduce((a, b) -> b).orElse(null);
            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
                        + " days of its settlement.");
            }
        }
        if (found == ClaimAction.VOID) {
            List<String> reasons = voidReasons.findAll(claim.sheetId());
            if (request.reason().isEmpty() ? !reasons.isEmpty() : !reasons.contains(request.reason())) {
                throw new InvalidClaimException("A void needs a reason chosen from the sheet's void reasons.");
            }
        }
        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
            throw new InvalidClaimException("A reason is required to reject a claim.");
        }
        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
                && settings.dated(claim.sheetId()).needsNote(claim.date(),
                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
        }
        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && claim.proofs() == 0
                && settings.dated(claim.sheetId()).needsProof(proofGrade(claim, people), claim.date(), due)) {
            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof to be "
                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
        }
        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
            found = ClaimAction.PEND;
            due = null;
        }
        String next = switch (found) {
            case OPEN -> nextNumber(claim, sheets, settings, periods);
            default -> claim.number();
        };
        applied.set(found);
        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
        number.set(new ClaimNumber(next));
        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
    }

    /** The grade whose proof threshold the claim falls under: its person's grade in force on its date (null: no person). */
    static String proofGrade(Claim claim, PersonRepository people) {
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : person.gradeOn(claim.date());
    }

    /** The number opening the claim gives it now: the sheet's next, or the next within its period under period numbering. */
    static String nextNumber(Claim claim, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods) {
        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
            return String.valueOf(sheets.nextClaimNumber(claim.sheetId()));
        }
        Period period = periods.findAll(claim.sheetId()).stream().filter((p) -> p.contains(claim.dueBy())).findFirst()
                .orElse(null);
        String prefix = period == null ? "X" : period.name();
        String key = period == null ? "" : period.name().toLowerCase();
        return prefix + "-" + sheets.nextPeriodClaimNumber(claim.sheetId(), key);
    }

    private static BigDecimal settledDue(Claim claim, SheetRepository sheets, PersonRepository people,
            RateRepository rates, SettingRepository settings, ClaimRepository claims) {
        return ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 * the number null unless it has one, the due fixed at settling (two decimals) or null while it is live,
 * the user who opened it or null while it is a draft, whether a statement bound it and the figure it bound
 * it to (two decimals; null: n/a), and the number of the claim a correction corrects (null: not a correction), and its due-by fixed when it was created (yyyy-MM-dd), and its status log, oldest first, and the date it is deferred until (yyyy-MM-dd; null: never deferred), and how many proofs it has been given, and the number of the claim it was split off (null: none), and the user whose open editor locks it (null: not locked), and whether it is a late entry (added while its period was soft-closed), and the last day it was reminded (yyyy-MM-dd; null: never), and its external reference (null: none), and its tags, sorted (none: empty), and the reason it was voided with (null: none), and its comments, oldest first, and the number of the bulk settle batch that settled it (null: none). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        List<LogLine> log, String deferredUntil, int proofs, String splitFrom, String lockedBy,
        boolean lateEntry, String reminded, String ref, List<String> tags, String voidReason,
        List<Comment> comments, Integer batch) {

    /** A line of the status log: the status, the user who gave it, the sheet's today then and the due then. */
    public record LogLine(String status, String by, String date, String due) {
    }

    /** A comment: the user who wrote it, the sheet's today then and its text. */
    public record Comment(String by, String date, String text) {
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log) {
        return from(claim, log, null, false, null, null, null, null, List.of(), null);
    }

    public static ClaimResponse from(Claim claim, List<ClaimLogLine> log, String lockedBy, boolean lateEntry,
            LocalDate reminded, String ref, String tags, String voidReason, List<ClaimComment> comments,
            Integer batch) {
        return new ClaimResponse(claim.id(), claim.personId(), claim.amount().toPlainString(),
                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
                claim.due() == null ? null : claim.due().setScale(2).toPlainString(), claim.openedBy(),
                claim.stated(), claim.statedDue() == null ? null : claim.statedDue().setScale(2).toPlainString(),
                claim.corrects(), claim.dueBy().toString(),
                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
                claim.deferredUntil() == null ? null : claim.deferredUntil().toString(),
                claim.proofs(), claim.splitFrom(), lockedBy, lateEntry,
                reminded == null ? null : reminded.toString(), ref,
                tags == null ? List.of() : List.of(tags.split(",")), voidReason,
                comments.stream().map((c) -> new Comment(c.by(), c.date().toString(), c.text())).toList(), batch);
    }
}
