20	/**
21	 * Moves the claim to the action's status; refused (400) when the claim's status does not allow it.
22	 * Opening gives the claim the sheet's next number; a voided claim keeps its number (it is never reused). While the
23	 * sheet's period numbering from date is set and its today is on or after it, opening instead gives the claim the next
24	 * number within the period containing its due-by (P1-1, P1-2, ...), or within the claims in no period (X-1, ...).
25	 * Opening, settling and voiding are refused (400) to a role the sheet's permission matrix does not allow them.
26	 * Opening records the user who opened it; that user cannot settle it (four eyes). Nor can the user who last edited
27	 * it (through its editor or its row's amount entry) settle or approve it. A deferred claim cannot be settled.
28	 * Settling fixes the claim's due at the greater of the sheet's floor in force on its date and its figure — at its person's grade's rate in force on the claim's date,
29	 * rounded by its policy date, or, when a statement bound the claim, the figure it was bound to — plus the late charge it has then, if overdue, frozen in; with no
30	 * figure it stays live. A clerk settling a claim whose due is above the sheet's clerk limit (a due of n/a is within any
31	 * limit) makes it PENDING instead, live and unfixed. A claim with no proofs whose due is above the proof threshold in force on its date —
32	 * its person's grade's own, when that grade has one then, else the sheet's — is refused settling or approving — before the clerk limit is considered, so it never goes PENDING.
33	 * A claim with an empty note whose due (as shown now) is above the sheet's note threshold in force on its date is refused opening. Only a steward approves a PENDING claim (fixing its due at its live
34	 * figure, plus any late charge, at that moment) — not the user who opened it — or rejects it, with a reason, back to OPEN.
35	 * Only a steward re-settles a SETTLED claim, fixing its due again at the figure it would have today as an open claim
36	 * bound by no statement (today's rates, grades, floor and late charge); its previous due is kept for the audit.
37	 * Only a steward voids a SETTLED claim, and only while the sheet's today is within 7 days of its settlement (the
38	 * status log's latest SETTLED date); it keeps its number and its frozen due, which leaves every total.
39	 * While the sheet's void reasons list is not empty, a void is refused (400) without a reason chosen from it; a reason
40	 * not on the list is always refused.
41	 */
42	public class ApplyClaimAction {
43	
44	    /** How many days after its settlement (the status log's SETTLED date) a steward may still void a SETTLED claim. */
45	    static final int VOID_SETTLED_DAYS = 7;
46	
47	    public void apply(@PathVariable("action") String action, @RequestParam("user") String user, @Val Claim claim,
48	            @Val ClaimActionRequest request, SheetRepository sheets,
49	            PersonRepository people, RateRepository rates, SettingRepository settings, PeriodRepository periods,
50	            VoidReasonRepository voidReasons, ClaimRepository claims, ClaimLogRepository logs, Out<ClaimAction> applied, Out<ClaimNumber> number, Out<PreviousDue> previous, Out<Claim> updated) throws InvalidClaimException {
51	        ClaimAction found = ClaimAction.of(action);
52	        if (found == null) {
53	            throw new InvalidClaimException("No such claim action: " + action);
54	        }
55	        if (!found.allowedFrom(claim.status())) {
56	            throw new InvalidClaimException("A " + claim.status() + " claim cannot be " + found.to() + ".");
57	        }
58	        if ((found == ClaimAction.OPEN || found == ClaimAction.SETTLE || found == ClaimAction.VOID)
59	                && !settings.find(claim.sheetId()).may(user, action)) {
60	            throw new InvalidClaimException("The user's role is not allowed to " + action + " a claim.");
61	        }
62	        if (found == ClaimAction.SETTLE && claim.deferred(sheets.today(claim.sheetId()))) {
63	            throw new InvalidClaimException("The claim is deferred until " + claim.deferredUntil() + ": it cannot be settled yet.");
64	        }
65	        if (found == ClaimAction.SETTLE && user.equals(claim.openedBy())) {
66	            throw new InvalidClaimException("The user who opened a claim cannot settle it.");
67	        }
68	        if (found == ClaimAction.APPROVE && user.equals(claim.openedBy())) {
69	            throw new InvalidClaimException("The user who opened a claim cannot approve it.");
70	        }
71	        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE)
72	                && user.equals(claims.editedBy(claim.sheetId(), claim.id()))) {
73	            throw new InvalidClaimException("The user who last edited a claim cannot " + action + " it.");
74	        }
75	        if ((found == ClaimAction.APPROVE || found == ClaimAction.REJECT)
76	                && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
77	            throw new InvalidClaimException("Only a steward can " + action + " a pending claim.");
78	        }
79	        if (found == ClaimAction.RESETTLE && settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
80	            throw new InvalidClaimException("Only a steward can re-settle a settled claim.");
81	        }
82	        if (found == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
83	            if (settings.find(claim.sheetId()).roleOf(user) != Role.STEWARD) {
84	                throw new InvalidClaimException("Only a steward can void a settled claim.");
85	            }
86	            LocalDate settledOn = logs.find(claim.sheetId(), claim.id()).stream()
87	                    .filter((l) -> l.status() == ClaimStatus.SETTLED).map(ClaimLogLine::date)
88	                    .reduce((a, b) -> b).orElse(null);
89	            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
90	                throw new InvalidClaimException("A settled claim can be voided only within " + VOID_SETTLED_DAYS
91	                        + " days of its settlement.");
92	            }
93	        }
94	        if (found == ClaimAction.VOID) {
95	            List<String> reasons = voidReasons.findAll(claim.sheetId());
96	            if (request.reason().isEmpty() ? !reasons.isEmpty() : !reasons.contains(request.reason())) {
97	                throw new InvalidClaimException("A void needs a reason chosen from the sheet's void reasons.");
98	            }
99	        }
100	        if (found == ClaimAction.REJECT && request.reason().isEmpty()) {
101	            throw new InvalidClaimException("A reason is required to reject a claim.");
102	        }
103	        BigDecimal due = found.settles() ? settledDue(found == ClaimAction.RESETTLE ? claim.asOpenUnbound() : claim, sheets, people, rates, settings, claims) : claim.due();
104	        if (found == ClaimAction.OPEN && (claim.note() == null || claim.note().isBlank())
105	                && settings.dated(claim.sheetId()).needsNote(claim.date(),
106	                        ClaimDueNow.of(claim, sheets, people, rates, settings, claims))) {
107	            throw new InvalidClaimException("The claim's due is above the note threshold: it needs a note to be opened.");
108	        }
109	        if ((found == ClaimAction.SETTLE || found == ClaimAction.APPROVE) && claim.proofs() == 0
110	                && settings.dated(claim.sheetId()).needsProof(proofGrade(claim, people), claim.date(), due)) {
111	            throw new InvalidClaimException("The claim's due is above the proof threshold: it needs a proof to be "
112	                    + (found == ClaimAction.SETTLE ? "settled" : "approved") + ".");
113	        }
114	        if (found == ClaimAction.SETTLE && !settings.find(claim.sheetId()).maySettle(user, due)) {
115	            found = ClaimAction.PEND;
116	            due = null;
117	        }
118	        String next = switch (found) {
119	            case OPEN -> nextNumber(claim, sheets, settings, periods);
120	            default -> claim.number();
121	        };
122	        applied.set(found);
123	        previous.set(new PreviousDue(claim.due(), claim.status() == ClaimStatus.SETTLED));
124	        number.set(new ClaimNumber(next));
125	        updated.set(claim.withStatus(found.to(), next, due, found == ClaimAction.OPEN ? user : claim.openedBy()));
126	    }
127	
128	    /** The grade whose proof threshold the claim falls under: its person's grade in force on its date (null: no person). */
129	    static String proofGrade(Claim claim, PersonRepository people) {
130	        Person person = people.find(claim.sheetId(), claim.personId());
131	        return person == null ? null : person.gradeOn(claim.date());
132	    }
133	
134	    /** The number opening the claim gives it now: the sheet's next, or the next within its period under period numbering. */
135	    static String nextNumber(Claim claim, SheetRepository sheets, SettingRepository settings,
136	            PeriodRepository periods) {
137	        LocalDate from = settings.periodNumberingFrom(claim.sheetId());
138	        if (from == null || sheets.today(claim.sheetId()).isBefore(from)) {
