235	
236	public class ValidateClaimRequest {
237	
238	    /** An amount, negative for a correction, with at most two decimals. */
239	    private static final Pattern AMOUNT = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");
240	
241	    /** A claim number: sheet-wide (1, 2, ...) or within a period (P1-1, X-1). */
242	    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,110}-\\d{1,9}");
243	
244	    public void validate(@RequestBody @Valid ClaimRequest request, Out<ClaimInput> input) throws InvalidClaimException {
245	        String amount = request.amount() == null ? "" : request.amount().trim();
246	        if (amount.isEmpty()) {
247	            throw new InvalidClaimException("An amount is required.");
248	        }
249	        if (!AMOUNT.matcher(amount).matches()) {
250	            throw new InvalidClaimException("The amount must be a number with at most two decimals.");
251	        }
252	        String date = request.date() == null ? "" : request.date().trim();
253	        LocalDate parsed = null;
254	        if (!date.isEmpty()) {
255	            try {
256	                parsed = LocalDate.parse(date);
257	            } catch (DateTimeParseException e) {
258	                throw new InvalidClaimException("The date must be yyyy-mm-dd.");
259	            }
260	        }
261	        String note = request.note() == null ? "" : request.note().strip();
262	        BigDecimal value = new BigDecimal(amount).setScale(2);
263	        String corrects = request.corrects() == null ? "" : request.corrects().trim();
264	        String number = null;
265	        if (value.signum() < 0) {
266	            if (!NUMBER.matcher(corrects).matches()) {
267	                throw new InvalidClaimException("A negative amount is a correction: name the number of the claim it corrects.");
268	            }
269	            number = corrects;
270	        } else if (!corrects.isEmpty()) {
271	            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
272	        }
273	        String ref = request.ref() == null ? "" : request.ref().strip();
274	        String tags = Claim.tags(request.tags());
275	        input.set(new ClaimInput(value, parsed, note, number, ref.isEmpty() ? null : ref, tags));
276	    }
277	}
