        if (!PERCENT.matcher(rate).matches()) {
            throw new InvalidRateException("The rate must be a percent of 0.00 or more, with at most two decimals.");
        }
        String from = request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
