import { deferred, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/** A date (yyyy-MM-dd) plus whole days. */
function plusDays(date: string, days: number): string {
  return new Date(Date.parse(`${date}T00:00:00Z`) + days * 86_400_000).toISOString().slice(0, 10);
}

/**
 * The date a claim is late after: its due-by, fixed when it was created, plus the grace days of its person's grade in
 * force on its date (0: none).
 */
export function lateFrom(claim: Claim, grace: number): string {
  return grace > 0 ? plusDays(claim.dueBy, grace) : claim.dueBy;
}

/** Whether a claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus the grace days is before the sheet's today. */
export function overdue(claim: Claim, today: string, grace = 0): boolean {
  return isOpen(claim) && !deferred(claim, today) && today !== '' && lateFrom(claim, grace) < today;
}

/** How many full 30-day periods a claim is overdue on the sheet's today, counted from its due-by plus the grace days: 0 unless it is overdue. */
export function latePeriods(claim: Claim, today: string, grace = 0): number {
  if (!overdue(claim, today, grace)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${lateFrom(claim, grace)}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}

/** The date the claim's nth (1, 2, ...) full 30-day overdue period ends: its due-by plus the grace plus 30 × n days (yyyy-MM-dd). */
export function lateBoundary(claim: Claim, period: number, grace = 0): string {
  return plusDays(lateFrom(claim, grace), period * 30);
}
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, total } from '../rates/rates';
import type { Rate } from '../rates/rates';
import type { GradeFrom, Hold } from '../people/people';
import { claimGrace } from '../settings/settings';
import type { DueRules } from '../settings/settings';
import { overdue } from './dueBy';

export { overdue } from './dueBy';

/**
 * A person's overdue claims that count (none of their open ones a hold covers): how many, and
 * their dues (late charges included) added up (skipping n/a).
 */
export function personOverdue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): { count: number; total: string } {
  const late = claims.filter((c) => counts(c, holds, rules.today) && overdue(c, rules.today, claimGrace(c, grades, rules)));
  return { count: late.length, total: total(late.map((c) => claimDue(c, rates, grades, rules))) };
}
import { counts, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { claimDue, total } from '../rates/rates';
import type { Rate } from '../rates/rates';
import type { GradeFrom, Hold } from '../people/people';
import type { DueRules } from '../settings/settings';

/** The age buckets a claim falls in by its days on the sheet's today: 0 to 30, 31 to 60, 61 or more. */
export type AgeBucket = '0-30' | '31-60' | '61';

/** A claim's age on the sheet's today, in days from its date; a claim dated after today is 0. */
export function claimAge(claim: Claim, today: string): number {
  if (today === '' || claim.date >= today) return 0;
  return Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.date}T00:00:00Z`)) / 86_400_000);
}

/** The bucket a claim's age falls in. */
export function ageBucket(claim: Claim, today: string): AgeBucket {
  const age = claimAge(claim, today);
  return age <= 30 ? '0-30' : age <= 60 ? '31-60' : '61';
}

/**
 * A person's OPEN and PENDING claims that count, their dues (late charges included) added up per age
 * bucket (skipping n/a; 0.00 with none).
 */
export function personAged(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
): Record<AgeBucket, string> {
  const live = claims.filter((c) => isOpen(c) && counts(c, holds, rules.today));
  const sum = (bucket: AgeBucket) =>
    total(live.filter((c) => ageBucket(c, rules.today) === bucket).map((c) => claimDue(c, rates, grades, rules)));
  return { '0-30': sum('0-30'), '31-60': sum('31-60'), '61': sum('61') };
}
import { counts, isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';
import type { Hold } from '../people/people';

/** How many days back from the sheet's today, today included, a claim keeps its person active. */
export const ACTIVE_DAYS = 30;

/** The first date (yyyy-MM-dd) of the active window ending on the sheet's today. */
const windowStart = (today: string) =>
  new Date(Date.parse(`${today}T00:00:00Z`) - (ACTIVE_DAYS - 1) * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether a person is active: they have an OPEN or PENDING claim that counts (not one a hold covers, nor a
 * deferred one) dated within the 30 days up to and including the sheet's today. `claims` are theirs.
 */
export function isActive(claims: Claim[], holds: Hold[], today: string): boolean {
  if (today === '') return false;
  const from = windowStart(today);
  return claims.some((c) => isOpen(c) && counts(c, holds, today) && c.date >= from && c.date <= today);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade recorded for a person, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: string; from: string | null };

/** The grade in force on the date (yyyy-MM-dd): the one recorded with the latest from-date on or before it. */
export function gradeOn(grades: GradeFrom[], date: string): string | undefined {
  let found: GradeFrom | undefined;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

/** A hold on a person, from its from-date to its to-date, both inclusive (yyyy-MM-dd; null: open-ended). */
export type Hold = { from: string | null; to: string | null };

/** Whether a hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to);

/**
 * The holds that apply to a person's live totals on the sheet's `today`: their own, and — from the day their
 * retirement date is reached — one covering every date, so their open and pending claims leave the totals as a
 * hold's would (settled ones, and ones a statement binds, still count).
 */
export const liveHolds = (p: { holds: Hold[]; retiredFrom: string | null }, today: string): Hold[] =>
  p.retiredFrom !== null && today !== '' && today >= p.retiredFrom ? [...p.holds, { from: null, to: null }] : p.holds;

/**
 * A person on the sheet as the store holds them; `grade` is the one in force on the sheet's today and
 * `grades` every grade recorded for them, each from its from-date; `version` counts their saves. `statementCount` counts
 * the statements taken of them; `statedTotal` is the last one's due-total and `statementDate` the
 * sheet's today when it was taken, both null before the first. `retired` is whether a retirement date is
 * set (whatever the date), `retiredFrom` that date, null while they are not retired. `held` is whether
 * they have any hold, `holds` each hold, oldest first: their open claims dated within one, and not bound by a
 * statement, count in no live total. `terms` is the person's own terms in days, null when they have none;
 * `contact` their contact (trimmed, lower-cased), null when they have none.
 */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: GradeFrom[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  terms: number | null;
  contact: string | null;
};

/**
 * The fields the person form submits; a blank `gradeFrom` is the sheet's today, blank `terms` none of their own,
 * blank `contact` none.
 */
export type PersonInput = { name: string; grade: string; gradeFrom: string; terms: string; contact: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

