import type { Claim } from '../claims/claims';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { claimDue, useRates } from './rates';

// A claim's due: the one fixed when it was settled, else the greater of the floor and its amount at the rate in force on its date for its person's grade (or its stated figure) plus any late charge while it is overdue.
export function ClaimDue({ claim, person }: { claim: Claim; person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  return <span data-testid="claim-due">{claimDue(claim, rates, person.grades, rules)}</span>;
}
import { useClaims } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { personDue, useRates } from './rates';

// A person's due-total: the figures of their claims that count, added up; n/a when their grade has no
// rate on the sheet's today, unless a settled or stated claim keeps a figure.
export function PersonDueTotal({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-due-total">{personDue(claims, rates, person.grades, liveHolds(person, rules.today), rules)}</td>;
}
import type { Person } from '../people/people';
import { useSheetToday } from '../session/sheetToday';
import { claimed, holdsById, useClaims } from './claims';

// What a person has claimed: the sum of their counting claims' amounts (not their open ones a hold covers).
export function PersonClaimed({ person }: { person: Person }) {
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  const today = useSheetToday();
  return <td data-testid="person-claimed">{claimed(claims, holdsById([person], today), today)}</td>;
}
import type { Claim } from '../claims/claims';
import { periodOf, usePeriods } from './periods';

// The period a claim belongs to: the one whose dates contain its due-by (fixed when it was created); blank with none.
export function ClaimPeriod({ claim }: { claim: Claim }) {
  const periods = usePeriods().data ?? [];
  return <span data-testid="claim-period">{periodOf(periods, claim.dueBy)?.name ?? ''}</span>;
}
import type { Claim } from '../claims/claims';
import type { Person } from '../people/people';
import { claimGrace, useDueRules } from '../settings/settings';
import { overdue } from './overdue';

// Whether a claim is overdue: OPEN (or PENDING), with its due-by plus the grace days of its person's grade before the sheet's today.
export function ClaimOverdue({ claim, person }: { claim: Claim; person: Person }) {
  const rules = useDueRules();
  return <span data-testid="claim-overdue">{overdue(claim, rules.today, claimGrace(claim, person.grades, rules)) ? 'yes' : 'no'}</span>;
}

