// The date this screen shows the sheet as of: every figure, flag, list and line as it stood at the
// end of that date, with the date standing in for the sheet's today. It belongs to this screen only
// (the `asof` search param); while it is set every change is refused (api/http).
export function AsOf() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [asOf] = useSearchParam('asof', asString);
  const [date, setDate] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  if (!user || !sheet) return null;
  const show = async (value: string) => {
    await navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value) next.asof = value;
        else delete next.asof;
        return next;
      },
      replace: true,
    });
    // Everything kept per sheet is re-read as of the new date.
    await queryClient.invalidateQueries({ queryKey: sheetKey(sheet) });
  };
  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = date.trim();
    setError('');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed) || Number.isNaN(Date.parse(trimmed))) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    void show(trimmed);
  };
  return (
    <form onSubmit={submit}>
      <span>
        As of: <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      </span>
      <input
        data-testid="asof-date"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="asof-set">
        Set as of
      </button>
      <button
        type="button"
        data-testid="asof-clear"
        onClick={() => {
          setError('');
          void show('');
        }}
      >
        Clear as of
      </button>
      {error && <span data-testid="asof-error">{error}</span>}
    </form>
  );
}
// Whether the person's last statement bound the claim to its figure.
export function ClaimStated({ claim }: { claim: Claim }) {
  return <span data-testid="claim-stated">{claim.stated ? 'yes' : 'no'}</span>;
}
const DATE = /^\d{4}-\d{2}-\d{2}$/;
// A person's statements: how many were taken, the last one's due-total and date, and the button that
// takes one — recording their due-total now and binding each counting claim to its figure now — and the
// button a steward cancels the last one with, making the claims it bound live again. A date beside the button takes the
// statement as of that day (on or before the sheet's today; blank: now), as the sheet stood at the end of it.
export function PersonStatement({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = usePersonError(person.id);
  const queryClient = useQueryClient();
  const [asof, setAsof] = useState('');
  const once = useOneAtATime();
  const take = useMutation({
    mutationFn: (date: string | null) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement?user=${encodeURIComponent(user)}`,
        { asof: date },
      ),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
    onError: () => setError('The statement could not be taken.'),
    // The date was for this statement only: the next one is taken now unless a date is typed again.
    onSettled: () => setAsof(''),
  });
  const cancel = useMutation({
    mutationFn: () =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/statement-cancel?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
      ]);
    },
    onError: () => setError('The statement could not be cancelled.'),
  });
  return (
    <td>
      <span data-testid="person-statement-count">{person.statementCount}</span>{' '}
      <span data-testid="person-stated-total">{person.statedTotal ?? ''}</span>{' '}
      <span data-testid="person-statement-date">{person.statementDate ?? ''}</span>{' '}
      <input
        data-testid="person-statement-asof"
        placeholder="As of yyyy-mm-dd (blank: now)"
        value={asof}
        onChange={(e) => {
          setAsof(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="person-statement"
        disabled={take.isPending}
        onClick={() => {
          setError('');
          const date = asof.trim();
          if (date && !DATE.test(date)) {
            setError('Type a date as yyyy-mm-dd.');
            return;
          }
          once(() => take.mutateAsync(date || null));
        }}
      >
        Statement
      </button>
      <button
        type="button"
        data-testid="person-unstate"
        disabled={cancel.isPending}
        onClick={() => {
          setError('');
          once(() => cancel.mutateAsync());
        }}
      >
        Cancel statement
      </button>
    </td>
  );
}
// The sheet's due-total: everyone's due-total added up, skipping those that are n/a, trimmed of the highest and lowest.
export function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  if (!user || !sheet) return null;
  const dues = people.map((p) => personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules));
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{trimmedTotal(dues)}</strong>
    </p>
  );
}
// The sheet's settled-total and open-total: everyone's added up (not trimmed).
export function SplitTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  if (!user || !sheet) return null;
  const each = people.map((p) =>
    personSplit(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules),
  );
  return (
    <p>
      Settled total: <strong data-testid="rollup-settled-total">{total(each.map((s) => s.settled))}</strong>, open
      total: <strong data-testid="rollup-open-total">{total(each.map((s) => s.open))}</strong>
    </p>
  );
}
// The sheet's overdue count and overdue-total: everyone's added up (the total trimmed of the highest and lowest).
export function OverdueTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  if (!user || !sheet) return null;
  const each = people.map((p) =>
    personOverdue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules),
  );
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>, totalling{' '}
      <strong data-testid="rollup-overdue-total">{trimmedTotal(each.map((o) => o.total))}</strong>
    </p>
  );
}
// For every tag ever used on the sheet, the due-total of the claims that count which carry it (a claim with two
// tags counts in both): their dues added up, skipping n/a — not capped, not trimmed.
export function TagTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const tags = useTags().data ?? [];
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  if (!user || !sheet || tags.length === 0) return null;
  const dues = new Map<string, string[]>(tags.map((t) => [t, []]));
  for (const p of people) {
    const holds = liveHolds(p, rules.today);
    for (const c of claims) {
      if (c.personId !== p.id || c.tags.length === 0 || !counts(c, holds, rules.today)) continue;
      const due = claimDue(c, rates, p.grades, rules);
      for (const t of c.tags) dues.get(t)?.push(due);
    }
  }
  return (
    <ul>
      {tags.map((t) => (
        <li key={t}>
          Tag {t} due total: <strong data-testid={`tag-${t}-due-total`}>{total(dues.get(t) ?? [])}</strong>
        </li>
      ))}
    </ul>
  );
}
// The sheet's claimed-total: everyone's counting claims added up (open ones a hold covers left out).
export function ClaimedTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = useClaims();
  const people = usePeople().data ?? [];
  const today = useSheetToday();
  if (!user || !sheet) return null;
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [], holdsById(people, today), today)}</strong>
    </p>
  );
}
// A person's patrons (their names, sorted) and the select and button that name one more: anyone else on
// the sheet who is not already their patron.
export function PersonPatrons({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const ids = patronIdsOf(usePatrons().data ?? [], person.id);
  const [chosen, setChosen] = useState('');
  const [error, setError] = usePersonError(person.id, 'patron');
  const queryClient = useQueryClient();
  const once = useOneAtATime();
  const names = people
    .filter((p) => ids.includes(p.id))
    .map((p) => p.name)
    .sort((a, b) => a.localeCompare(b));
  const offered = people.filter((p) => p.id !== person.id && !ids.includes(p.id));
  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons?user=${encodeURIComponent(user)}`,
        { patronId },
      ),
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: patronsKey(sheet) });
    },
    onError: () => setError('The patron could not be added.'),
  });
  const submit = () => {
    setError('');
    if (!chosen) {
      setError('Choose a patron.');
      return;
    }
    once(() => add.mutateAsync(Number(chosen)));
  };
  return (
    <td>
      <span data-testid="person-patrons">{names.join(', ')}</span>{' '}
      <select
        data-testid="person-patron-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          setError('');
        }}
      >
        <option value="" />
        {offered.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
          </option>
        ))}
      </select>
      <button type="button" data-testid="person-patron-add" disabled={add.isPending} onClick={submit}>
        Add patron
      </button>
      {error && <span data-testid="person-patron-error">{error}</span>}
    </td>
  );
}
/** How many days back from the sheet's today, today included, a patron's settled claim counts toward backing. */
const BACKING_DAYS = 90;
/** The first date (yyyy-MM-dd) of the backing window ending on the sheet's today. */
const backingStart = (today: string) =>
  new Date(Date.parse(`${today}T00:00:00Z`) - (BACKING_DAYS - 1) * 86_400_000).toISOString().slice(0, 10);
// A person's backing: their patrons' SETTLED claims dated within the 90 days up to and including the sheet's
// today, each at the figure frozen when it was settled, added up; 0.00 with none.
export function PersonBacking({ person }: { person: Person }) {
  const ids = patronIdsOf(usePatrons().data ?? [], person.id);
  const today = useDueRules().today;
  const claims = useClaims().data ?? [];
  const from = today === '' ? '' : backingStart(today);
  const dues = claims
    .filter((c) => ids.includes(c.personId) && c.status === 'SETTLED' && today !== '' && c.date >= from && c.date <= today)
    .map((c) => c.due ?? NA);
  return <td data-testid="person-backing">{total(dues)}</td>;
}

