/**
 * Takes the person's statement: records their due-total now, binds each of their claims that counts to the
 * figure it has now (a live one at its rate alone, not raised to the floor), and unbinds (live again) each that does not. The due-total is their counting claims'
 * dues added up, at most the cap in force on the sheet's today (each the greater of the floor in force on its date and its figure plus any late charge on
 * it — the charge and floor are never bound, they keep following the sheet's today and settings); n/a when their grade on the sheet's today has no rate there and no counting claim has a figure (kept, or at the
 * rate for the grade in force on its date).
 * <p>
 * Taken as of a date (on or before the sheet's today), it works on the sheet as it stood at the end of that date — every
 * change made while the sheet's today was on or before it, none made later — with that date standing in for the
 * sheet's today: it binds the person's claims that counted then to their figures then, unbinds every other claim of
 * theirs, and records that day's due-total and that date. Refused (400) for a date after the sheet's today, or one
 * when the person was not yet on the sheet.
 */
public class TakeStatement {
    public void take(@Val Person person, @Val StatementAsOf asOf, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SheetRepository sheets, SettingRepository settings, SheetDayRepository days,
            Out<Statement> statement, Out<Person> updated) throws InvalidStatementException {
        LocalDate today = sheets.today(person.sheetId());
        LocalDate on = asOf.date() == null ? today : asOf.date();
        if (on.isAfter(today)) {
            throw new InvalidStatementException("A statement cannot be taken as of a date after the sheet's today.");
        }
        List<Claim> personClaims = claims.findForPerson(person.sheetId(), person.id());
        SheetState then = asOf.date() == null ? null : days.asOf(person.sheetId(), on);
        Person thenPerson = person;
        List<Claim> thenClaims = personClaims;
        List<Rate> sheetRates;
        DatedSettings dated;
        LocalDate policyDate;
        if (then == null) {
            sheetRates = rates.findAll(person.sheetId());
            dated = settings.dated(person.sheetId());
            policyDate = settings.policyDate(person.sheetId());
        } else {
            thenPerson = then.person(person.id());
            if (thenPerson == null) {
                throw new InvalidStatementException(person.name() + " was not on the sheet on " + on + ".");
            }
            thenClaims = then.claimsOf(person.id());
            sheetRates = then.rates();
            dated = then.dated();
            policyDate = then.policyDate();
        }
        Rounding rounding = Rounding.of(policyDate == null ? on : policyDate, thenClaims);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        Map<Long, BigDecimal> figures = new HashMap<>();
        for (Claim claim : thenClaims) {
            if (!thenPerson.counts(claim, on)) {
                continue;
            }
            boolean fixed = claim.keepsFigure();
            BigDecimal rate = Rate.inForce(sheetRates, thenPerson.gradeOn(claim.date()), claim.date());
            BigDecimal figure = claim.figure(rate, rounding);
            figures.put(claim.id(), figure);
            counted++;
            kept |= fixed || figure != null;
            if (figure != null) {
                total = total.add(claim.due(rate, dated.floorOn(claim.date()), dated.lateCharge(on, thenPerson), rounding));
            }
        }
        for (Claim claim : personClaims) {
            boolean stated = figures.containsKey(claim.id());
            claims.bindStatement(claim, stated, stated ? figures.get(claim.id()) : null);
        }
        String dueTotal = Rate.inForce(sheetRates, thenPerson.gradeOn(on), on) == null && !kept ? "n/a"
                : Cap.apply(dated.capOn(on), total).setScale(2).toPlainString();
        statement.set(new Statement(person.name(), dueTotal, counted, asOf.date()));
        updated.set(people.recordStatement(person, dueTotal, on));
    }
}


/**
 * Cancels the person's last statement: the claims it bound are live again (a figure bound by a statement before it
 * is not restored), and the person shows one statement fewer, with the due-total and date of the one before it (or
 * none). Refused (400) when the user is not a steward or the person has no statement.
 */
public class CancelStatement {
    public void cancel(@Val Person person, @RequestParam("user") String user, SettingRepository settings,
            ClaimRepository claims, PersonRepository people, Out<CancelledStatement> cancelled, Out<Person> updated)
            throws InvalidStatementException {
        if (settings.find(person.sheetId()).roleOf(user) != Role.STEWARD) {
            throw new InvalidStatementException("Only a steward may cancel a statement.");
        }
        if (person.statementCount() <= 0) {
            throw new InvalidStatementException(person.name() + " has no statement to cancel.");
        }
        cancelled.set(new CancelledStatement(person.name(), person.statedTotal()));
        claims.unbindStatement(person.sheetId(), person.id());
        updated.set(people.cancelStatement(person));
    }
}


/** Refuses (400) a statement whose as-of date is not yyyy-mm-dd; a blank one takes the statement now. */
public class ValidateStatementRequest {
    public void validate(@RequestBody @Valid StatementRequest request, Out<StatementAsOf> asOf)
            throws InvalidStatementException {
        String value = request == null || request.asof() == null ? "" : request.asof().trim();
        if (value.isEmpty()) {
            asOf.set(new StatementAsOf(null));
            return;
        }
        try {
            asOf.set(new StatementAsOf(LocalDate.parse(value)));
        } catch (DateTimeParseException e) {
            throw new InvalidStatementException("A statement's date must be yyyy-mm-dd.");
        }
    }
}


/**
 * Closes a period, fixing its due-total as it stands now: the dues (figures plus any late charge, as they are now) of
 * the claims dated in it that count by their status at the period's end, added up (n/a skipped), and each person's
 * share of it (0.00 for a person with none). Used by a close by hand and by the automatic close when today changes.
 */
@Component
public class PeriodCloser {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public PeriodCloser(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) {
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** The same period, closed with its due-total and each person's due-total fixed as they stand now. */
    public Period close(Period period) {
        return fix(period, false);
    }

    /** The same period, soft-closed with its due-total and each person's due-total fixed as they stand now. */
    public Period softClose(Period period) {
        return fix(period, true);
    }

    private Period fix(Period period, boolean soft) {
        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, Function.identity()));
        List<Rate> sheetRates = rates.findAll(period.sheetId());
        DatedSettings dated = settings.dated(period.sheetId());
        LocalDate today = sheets.today(period.sheetId());
        List<Claim> sheetClaims = claims.findAll(period.sheetId());
        Map<Long, List<ClaimLogLine>> sheetLogs = logs.findAll(period.sheetId());
        Rounding rounding = settings.rounding(period.sheetId(), today, sheetClaims);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> perPerson = new HashMap<>();
        for (Long id : byId.keySet()) {
            perPerson.put(id, BigDecimal.ZERO.setScale(2));
        }
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.personId());
            if (person == null || !period.counts(claim, sheetLogs.getOrDefault(claim.id(), List.of()), person, today)) {
                continue;
            }
            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
                    dated.floorOn(claim.date()), dated.lateCharge(today, person), rounding);
            if (figure != null) {
                total = total.add(figure);
                perPerson.merge(person.id(), figure, BigDecimal::add);
            }
        }
        return soft ? period.softClose(total, perPerson) : period.close(total, perPerson);
    }
}


/**
 * A period of a sheet: its name (unique on the sheet) and its from and to dates, both inclusive. A closed
 * period keeps the due-total fixed when it was closed ({@code closedTotal}; null while open) and each person's
 * due-total for it then ({@code personTotals}, by person id; empty while open). A soft-closed period
 * ({@code softClosed}; never also {@code closed}) keeps its figures fixed the same way, but claims due by a date in it can
 * still be added and changed.
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, Map<Long, BigDecimal> personTotals, boolean softClosed) {

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null, Map.of(), false);
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean fixed() {
        return closed || softClosed;
    }

    /** Whether the period shares a day with the other. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to()) && !other.from().isAfter(to);
    }

    /** Whether the date falls in the period, both ends included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /**
     * The status the claim had at the end of the period's last day, as its status log (oldest first) records it: the
     * last line logged on or before it; null when it was added after. A claim with no log is taken at its status now.
     */
    public ClaimStatus statusAtEnd(Claim claim, List<ClaimLogLine> log) {
        if (log.isEmpty()) {
            return claim.status();
        }
        ClaimStatus status = null;
        for (ClaimLogLine line : log) {
            if (!line.date().isAfter(to)) {
                status = line.status();
            }
        }
        return status;
    }

    /**
     * Whether the claim counts toward the period: due by a date in it and OPEN, PENDING or SETTLED at the period's end, left
     * out as the live rules say while it is deferred on today, or when it was open then, is open still, a hold of its
     * person covers it (or their retirement date is reached) and no statement binds it (a hold leaves out only open
     * claims). A settled claim voided since leaves it.
     */
    public boolean counts(Claim claim, List<ClaimLogLine> log, Person person, LocalDate today) {
        if (!contains(claim.dueBy())) {
            return false;
        }
        ClaimStatus then = statusAtEnd(claim, log);
        if (then == ClaimStatus.SETTLED) {
            return claim.status() != ClaimStatus.VOID;
        }
        if (then == null || !then.open() || claim.deferred(today)) {
            return false;
        }
        return !claim.status().open() || claim.bound() || !person.heldOn(claim.date(), today);
    }

    /** The same period, closed with its due-total and each person's due-total fixed. */
    public Period close(BigDecimal total, Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, true, total, Map.copyOf(perPerson), false);
    }

    /** The same period, soft-closed with its due-total and each person's due-total fixed. */
    public Period softClose(BigDecimal total, Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, false, total, Map.copyOf(perPerson), true);
    }

    /** The same period with these fixed per-person due-totals. */
    public Period withPersonTotals(Map<Long, BigDecimal> perPerson) {
        return new Period(sheetId, name, from, to, closed, closedTotal, Map.copyOf(perPerson), softClosed);
    }

    /** The same period, open again with its due-total live. */
    public Period reopen() {
        return new Period(sheetId, name, from, to, false, null, Map.of(), false);
    }
}


/**
 * Once the sheet's new today is set, closes every open period whose to-date plus the sheet's grace days is before it
 * (none while the grace days are off), in order of their to-dates, as a close by hand would; each is recorded as
 * PERIOD_CLOSED with auto=yes.
 */
public class AutoClosePeriods {
    public void close(@Val Sheet sheet, PeriodRepository periods, PeriodCloser closer, SettingRepository settings,
            @RequestParam("user") String user, Audit audit) {
        Integer graceDays = settings.graceDays(sheet.id());
        if (graceDays == null) {
            return;
        }
        for (Period period : periods.findAll(sheet.id()).stream().sorted(Comparator.comparing(Period::to)).toList()) {
            if (period.fixed() || !period.to().plusDays(graceDays).isBefore(sheet.today())) {
                continue;
            }
            Period closed = closer.close(period);
            periods.saveClosed(closed);
            audit.record("PERIOD_CLOSED sheet=" + closed.sheetId() + " by=" + user + " period=" + closed.name()
                    + " total=" + closed.closedTotal().setScale(2).toPlainString() + " auto=yes");
        }
    }
}


/**
 * Closes the period, fixing its due-total as it stands now (see {@link PeriodCloser}). Refused (400) when it is
 * already closed, or when the permission matrix does not allow the user's role closing.
 */
public class ClosePeriod {
    public void close(@Val Period period, PeriodCloser closer, SettingRepository settings,
            @RequestParam("user") String user, Out<Period> closed) throws InvalidPeriodException {
        if (!settings.find(period.sheetId()).may(user, Permissions.CLOSE)) {
            throw new InvalidPeriodException("The user's role is not allowed to close a period.");
        }
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
        }
        closed.set(closer.close(period));
    }
}


/**
 * Soft-closes the period, fixing its due-total and each person's figure as they stand now (see {@link PeriodCloser}),
 * while claims dated in it can still be added and changed. Refused (400) when it is already closed or soft-closed, or
 * when the permission matrix does not allow the user's role closing.
 */
public class SoftClosePeriod {
    public void softClose(@Val Period period, PeriodCloser closer, SettingRepository settings,
            @RequestParam("user") String user, Out<Period> closed) throws InvalidPeriodException {
        if (!settings.find(period.sheetId()).may(user, Permissions.CLOSE)) {
            throw new InvalidPeriodException("The user's role is not allowed to close a period.");
        }
        if (period.fixed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
        }
        closed.set(closer.softClose(period));
    }
}


/**
 * Reopens the period, making its due-total live again. Refused (400) when the permission matrix does not allow the user's role reopening (standing rule: a steward) or the period
 * is neither closed nor soft-closed.
 */
public class ReopenPeriod {
    public void reopen(@Val Period period, @RequestParam("user") String user, SettingRepository settings,
            Out<Period> reopened) throws InvalidPeriodException {
        if (!settings.find(period.sheetId()).may(user, Permissions.REOPEN)) {
            throw new InvalidPeriodException("The user's role is not allowed to reopen a period.");
        }
        if (!period.fixed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is not closed.");
        }
        reopened.set(period.reopen());
    }
}


/** Refuses a period whose name another period on the sheet already has (ignoring case), or whose dates overlap another's. */
public class CheckPeriodFits {
    public void check(@Val Period period, PeriodRepository repository) throws InvalidPeriodException {
        for (Period other : repository.findAll(period.sheetId())) {
            if (other.name().equalsIgnoreCase(period.name())) {
                throw new InvalidPeriodException("The name " + period.name() + " is already in use.");
            }
            if (other.overlaps(period)) {
                throw new InvalidPeriodException("The dates overlap the period " + other.name() + ".");
            }
        }
    }
}

