/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' dues (live figures rounded by its policy date, plus
 * any late charge, at the late percent in force on each 30-day boundary, on the overdue ones, then raised to the floor in force on each claim's date) added up, at most the cap in force on the sheet's today; n/a when their grade on the sheet's today has no
 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). Their overdue-total
 * is the dues of their overdue counting claims added up (skipping n/a, not capped). The sheet's totals add these up, skipping n/a;
 * its due-total and overdue-total leave out the single highest and lowest person's figure when three or more have one.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        DatedSettings dated = settings.dated(sheetId);
        BigDecimal cap = dated.capOn(today);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim, today)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.keepsFigure();
                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()),
                        dated.floorOn(claim.date()), dated.lateCharge(today, person), rounding);
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                    if (claim.overdue(today, dated.graceFor(person, claim))) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            due = Cap.apply(cap, due);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dues.add(due);
            }
            overdues.add(overdue);
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due), show(overdue)));
        }
        return new Rollup(figures, show(claimedTotal), show(trimmedTotal(dues)), show(trimmedTotal(overdues)));
    }

    /** The figures added up, leaving out the single highest and single lowest when there are three or more. */
    private static BigDecimal trimmedTotal(List<BigDecimal> values) {
        List<BigDecimal> sorted = new ArrayList<>(values);
        sorted.sort(null);
        if (sorted.size() >= 3) {
            sorted = sorted.subList(1, sorted.size() - 1);
        }
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}


/**
 * Follows a change's own records with one ROLLUP line per person whose figures it moved (a person new to the
 * sheet counts as moved), in the order they were added, then a TOTALS line when the sheet's totals moved.
 */
public class AuditRollup {
    public void audit(@Val RollupBefore before, @PathVariable("sheetId") String sheetId,
            @RequestParam("user") String user, RollupService rollups, Audit audit) {
        Rollup was = before.rollup();
        Rollup now = rollups.compute(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        for (Map.Entry<Long, Rollup.Figures> entry : now.people().entrySet()) {
            Rollup.Figures figures = entry.getValue();
            if (!figures.sameAs(was.people().get(entry.getKey()))) {
                audit.record("ROLLUP" + prefix + " person=" + figures.name() + " claimed=" + figures.claimed()
                        + " due-total=" + figures.dueTotal() + " overdue-total=" + figures.overdueTotal());
            }
        }
        if (!now.claimedTotal().equals(was.claimedTotal()) || !now.dueTotal().equals(was.dueTotal())
                || !now.overdueTotal().equals(was.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + now.claimedTotal() + " due-total="
                    + now.dueTotal() + " overdue-total=" + now.overdueTotal());
        }
    }
}


/**
 * Before the sheet's today changes, records one SNAPSHOT line per person, in list order, with their due-total as it
 * stood on the day being left.
 */
public class AuditSnapshot {
    public void audit(@Val RollupBefore before, @PathVariable("sheetId") String sheetId,
            @RequestParam("user") String user, Audit audit) {
        for (Rollup.Figures figures : before.rollup().people().values()) {
            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
                    + " due-total=" + figures.dueTotal());
        }
    }
}


/**
 * Works out again the due-by of every claim on the sheet that is not SETTLED or VOID and is due by on or after the new
 * holiday: from the claim's date, with the terms it was fixed with, over the holidays now on the sheet.
 */
public class RefixDueBys {
    public void refix(@Val Holiday holiday, ClaimRepository claims) {
        claims.refixDueBys(holiday.sheetId(), holiday.date());
    }
}


/** Refuses (400) a holiday whose date is not yyyy-mm-dd or is already on the sheet's list. */
public class ValidateHolidayRequest {
    public void validate(@Val Sheet sheet, @RequestBody @Valid HolidayRequest request, HolidayRepository holidays,
            Out<Holiday> holiday) throws InvalidHolidayException {
        String text = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidHolidayException("A holiday's date must be yyyy-mm-dd.");
        }
        if (holidays.exists(sheet.id(), date)) {
            throw new InvalidHolidayException(date + " is already a holiday.");
        }
        holiday.set(new Holiday(sheet.id(), date));
    }
}
