/** A new DRAFT claim; its due-by is fixed now: its date plus the person's own terms, else
 * those of their grade, else the sheet's, each as in force on that date. */
public class BuildClaim {
    public void build(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, Out<Claim> claim) {
        LocalDate date = input.date() != null ? input.date() : sheets.entryDate(person.sheetId());
        LocalDate dueBy = NewDueBy.of(date, person, settings, holidays);
        claim.set(new Claim(null, person.sheetId(), person.id(), input.amount(), date, input.note(), ClaimStatus.DRAFT,
                null, null, null, false, null, input.corrects(), dueBy));
    }
}


public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim, SheetRepository sheets, Out<Claim> updated) {
        updated.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), input.amount(),
                input.date() != null ? input.date() : sheets.entryDate(claim.sheetId()), input.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(), input.corrects(),
                claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom()));
    }
}


/**
 * Splits the text into lines of name,amount,date,note (the note may hold commas; the date may be blank; the note
 * may be absent; blank lines are skipped) and checks each with exactly the claim form's rules. Nothing pasted is
 * refused, as is a line without a name or amount. A pasted claim corrects nothing, so a negative amount is refused.
 * A note ending " #<reference>" gives the claim that external reference, which is not part of the note; a reference
 * an earlier line gave, ignoring case, is refused.
 */
public class ValidatePasteRequest {
    public void validate(@RequestBody @Valid PasteRequest request, Out<PastedLines> pasted) throws InvalidClaimException {
        String text = request.text() == null ? "" : request.text();
        List<PastedLine> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        int number = 0;
        for (String line : text.split("\\r?\\n")) {
            number++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            String name = fields[0].strip();
            if (name.isEmpty()) {
                throw new InvalidClaimException("Line " + number + ": a name is required.");
            }
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + number + ": an amount is required.");
            }
            // The claim form's field limits, which its request checks on binding.
            if (fields[1].length() > 30 || (fields.length > 2 && fields[2].length() > 30)
                    || (fields.length > 3 && fields[3].length() > 1000)) {
                throw new InvalidClaimException("Line " + number + ": a field is too long.");
            }
            String note = fields.length > 3 ? fields[3].strip() : "";
            String ref = "";
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2).strip();
                note = note.substring(0, hash);
            }
            if (ref.length() > 120) {
                throw new InvalidClaimException("Line " + number + ": a field is too long.");
            }
            ClaimRequest claim = new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "", note, "", ref, "");
            ClaimInput[] input = new ClaimInput[1];
            try {
                new ValidateClaimRequest().validate(claim, value -> input[0] = value);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
            if (input[0].ref() != null && !refs.add(input[0].ref().toLowerCase(Locale.ROOT))) {
                throw new InvalidClaimException("Line " + number + ": the reference " + input[0].ref()
                        + " is already given by an earlier line.");
            }
            lines.add(new PastedLine(name, input[0], null));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note.");
        }
        pasted.set(new PastedLines(lines));
    }
}


/**
 * Finds each line's person by name (as names are compared: ignoring case) and checks its claim against them with the
 * claim form's rules: no claim after the person's retirement date, none due by (its date plus the terms it would get) inside a closed period, no external reference another claim on the sheet has. Any line refused
 * refuses the whole paste, before anything is written.
 */
public class FindPastedPeople {
    public void find(@Val PastedLines pasted, @Val Sheet sheet, PersonRepository people, SheetRepository sheets,
            PeriodRepository periods, SettingRepository settings, HolidayRepository holidays, ClaimRepository claims) throws InvalidClaimException {
        List<PastedLine> found = new ArrayList<>();
        int number = 0;
        for (PastedLine line : pasted.lines()) {
            number++;
            Person person = people.findByName(sheet.id(), line.name());
            if (person == null) {
                throw new InvalidClaimException("Line " + number + ": " + line.name() + " is not on the sheet.");
            }
            try {
                new CheckClaimInputNotRetired().check(line.input(), person, sheet.id(), sheets);
                new CheckClaimInputPeriodOpen().check(line.input(), person, sheet.id(), sheets, settings, holidays,
                        periods);
                if (line.input().ref() != null && claims.refUsed(sheet.id(), line.input().ref(), null)) {
                    throw new InvalidClaimException("The reference " + line.input().ref() + " is already used on the sheet.");
                }
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
            found.add(new PastedLine(line.name(), line.input(), person));
        }
        pasted.lines().clear();
        pasted.lines().addAll(found);
    }
}


/**
 * Adds a DRAFT claim per pasted line, in order, each as the claim form's add does: due-by fixed from its date and
 * its person's grade's terms, its DRAFT status logged, and recorded as CLAIM_ADDED (with its reference, if any) (and LATE_ENTRY when its period is soft-closed).
 */
public class SavePastedClaims {
    public void save(@Val PastedLines pasted, @RequestParam("user") String user, SheetRepository sheets,
            SettingRepository settings, HolidayRepository holidays, PersonRepository people, RateRepository rates,
            ClaimRepository claims, ClaimLogRepository logs, Audit audit, LateEntries lateEntries, Out<PasteResult> result) {
        int added = 0;
        for (PastedLine line : pasted.lines()) {
            Person person = line.person();
            LocalDate date = line.input().date() != null ? line.input().date() : sheets.entryDate(person.sheetId());
            LocalDate dueBy = NewDueBy.of(date, person, settings, holidays);
            Claim claim = claims.save(new Claim(null, person.sheetId(), person.id(), line.input().amount(), date,
                    line.input().note(), ClaimStatus.DRAFT, null, null, null, false, null, line.input().corrects(),
                    dueBy));
            BigDecimal due = ClaimDueNow.of(claim, sheets, people, rates, settings, claims);
            logs.append(claim.sheetId(), new ClaimLogLine(claim.id(), claim.status(), user,
                    sheets.today(claim.sheetId()), due == null ? "n/a" : due.setScale(2).toPlainString()));
            claims.saveRef(claim, line.input().ref());
            audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + user + " person=" + person.name()
                    + " amount=" + claim.amount().setScale(2).toPlainString() + " date=" + claim.date()
                    + Claim.auditRef(line.input().ref()));
            lateEntries.mark(claim, person, user);
            added++;
        }
        result.set(new PasteResult(added));
    }
}


/**
 * Checks the bar on the person and claim forms' terms before anything is written: a blank name, or an
 * amount the claim form refuses, is refused. The claim is dated the sheet's entry date, else its today, with an empty note.
 */
public class ValidateQuickAddRequest {
    public void validate(@RequestBody @Valid QuickAddRequest request, Out<QuickAddRequest> body,
            Out<ClaimInput> input) throws InvalidPersonException, InvalidClaimException {
        String name = request.name() == null ? "" : request.name().strip();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        new ValidateClaimRequest().validate(new ClaimRequest(request.amount(), "", "", "", "", ""), input);
        body.set(new QuickAddRequest(name, request.amount()));
    }
}


/** The person on the sheet with the typed name (ignoring case), or a new, unsaved one with grade A. */
public class FindQuickPerson {
    public void find(@Val QuickAddRequest request, @Val Sheet sheet, PersonRepository repository,
            Out<Person> person) {
        Person found = repository.findByName(sheet.id(), request.name());
        person.set(found != null ? found : new Person(null, sheet.id(), request.name(), "A", 0, 0, null, null, null, List.of()));
    }
}


/** Adds the person when they are new to the sheet, recording it as the person form's add does. */
public class SaveQuickPerson {
    public void save(@Val Person person, PersonRepository repository, @RequestParam("user") String user,
            Audit audit, Out<Person> saved) {
        if (person.id() != null) {
            return;
        }
        Person stored = repository.save(person);
        audit.record("PERSON_ADDED sheet=" + stored.sheetId() + " by=" + user + " name=" + stored.name()
                + " grade=" + stored.grade());
        saved.set(stored);
    }
}


public class ValidateTodayRequest {
    public void validate(@RequestBody @Valid TodayRequest request, Out<LocalDate> today) throws InvalidTodayException {
        String value = request.today() == null ? "" : request.today().trim();
        if (value.isEmpty()) {
            today.set(LocalDate.now()); // the default: the real date
            return;
        }
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(value);
        }
    }
}


/** Archives the sheet; only a steward (given or delegated) may. */
public class ApplySheetArchived {
    public void apply(@Val Sheet sheet, @RequestParam("user") String user, SettingRepository settings,
            Out<Sheet> updated) throws SheetArchivedException {
        if (settings.find(sheet.id()).roleOf(user) != Role.STEWARD) {
            throw new SheetArchivedException("Only a steward can archive the sheet.");
        }
        updated.set(new Sheet(sheet.id(), sheet.today(), true));
    }
}


/** Refuses (400) any change to an archived sheet: it runs first, so a refused change writes nothing. */
public class CheckNotArchived {
    public void check(@PathVariable("sheetId") String sheetId, SheetRepository sheets) throws SheetArchivedException {
        if (sheets.isArchived(sheetId)) {
            throw new SheetArchivedException("An archived sheet cannot be changed.");
        }
    }
}


/**
 * Adds a hold to the person, from the date given (blank: the sheet's today) to its to-date (blank: no end); a
 * to-date before the from-date is refused (400).
 */
public class HoldPerson {
    public void hold(@Val Person person, @Val Hold hold, PersonRepository people, SheetRepository sheets,
            Out<Person> updated) throws InvalidPersonException {
        Hold dated = hold.from() != null ? hold : new Hold(sheets.today(person.sheetId()), hold.to());
        if (dated.to() != null && dated.to().isBefore(dated.from())) {
            throw new InvalidPersonException("A hold's to-date must not be before its from-date.");
        }
        updated.set(people.hold(person, dated));
    }
}


/** Retires the person from the date given, or the sheet's today when it was left blank. */
public class RetirePerson {
    public void retire(@Val Person person, @Val Retirement retirement, PersonRepository people,
            SheetRepository sheets, Out<Person> updated) {
        updated.set(people.retire(person,
                retirement.from() != null ? retirement.from() : sheets.today(person.sheetId())));
    }
}


/** Defers the claim until the deferral's date. */
public class DeferClaim {
    public void defer(@Val Claim claim, @Val Deferral deferral, ClaimRepository repository, Out<Claim> deferred) {
        Claim next = claim.deferTo(deferral.until());
        repository.defer(next);
        deferred.set(next);
    }
}


/**
 * Moves the claim to its new date, keeping its due-by, its number and any statement figure. Its period is the one
 * containing its due-by, so a re-date never moves it to another period (nor another period numbering sequence).
 */
public class RedateClaim {
    public void redate(@Val Claim claim, @Val Redating redating, ClaimRepository repository, Out<Claim> redated) {
        Claim moved = claim.redateTo(redating.to(), claim.number());
        repository.redate(moved);
        redated.set(moved);
    }
}


/** Moves the claim to its new person, keeping its number and date; it loses any statement figure. */
public class ReassignClaim {
    public void reassign(@Val Claim claim, @Val Reassignment reassignment, ClaimRepository repository,
            Out<Claim> moved) {
        moved.set(repository.reassign(claim, reassignment.to().id()));
    }
}


/** Reads the re-date's body once, publishing its new date; refuses (400) a missing or malformed date. */
public class ValidateRedateRequest {
    public void validate(@RequestBody RedateRequest request, Out<NewClaimDate> date) throws InvalidClaimException {
        String typed = request == null || request.date() == null ? "" : request.date().trim();
        if (typed.isEmpty()) {
            throw new InvalidClaimException("Type the claim's new date.");
        }
        try {
            date.set(new NewClaimDate(LocalDate.parse(typed)));
        } catch (DateTimeParseException ex) {
            throw new InvalidClaimException("Type a date as yyyy-mm-dd.");
        }
    }
}


/** Reads the deferral's body once, publishing its date; refuses (400) a missing or malformed date. */
public class ValidateDeferRequest {
    public void validate(@RequestBody DeferRequest request, Out<Deferral> deferral) throws InvalidClaimException {
        String until = request == null || request.until() == null ? "" : request.until().trim();
        if (until.isEmpty()) {
            throw new InvalidClaimException("Type the date to defer the claim until.");
        }
        try {
            deferral.set(new Deferral(LocalDate.parse(until)));
        } catch (DateTimeParseException ex) {
            throw new InvalidClaimException("Type a date as yyyy-mm-dd.");
        }
    }
}

