@Order(Ordered.HIGHEST_PRECEDENCE)
public class AsOfFilter extends OncePerRequestFilter {

    private static final Pattern SHEET_READ = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final SheetDayRepository days;

    public AsOfFilter(SheetDayRepository days) {
        this.days = days;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
     * The date a new claim left without one takes: the sheet's entry date while it is set, else its today.
     */
    public LocalDate entryDate(String id) {
        List<Date> found = jdbc.query("SELECT entry_date FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("entry_date"), id);
        return found.isEmpty() || found.get(0) == null ? today(id) : found.get(0).toLocalDate();
    }

    /**
     * Takes the sheet's next claim number (1 for its first) in one atomic statement, so two claims
     * opened at the same moment never get the same number; a number taken is never given out again.
     */
    public int nextClaimNumber(String id) {
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, id);
    }


/**
 * Refuses (400) a delegation made by anyone but a steward (a steward given the role, not one by delegation), one with
 * a blank user name, dates not yyyy-mm-dd or a to-date before its from-date; a blank date is the sheet's today.
 */
public class ValidateDelegationRequest {
    public void validate(@Val Sheet sheet, @RequestParam("user") String user, @RequestBody @Valid DelegationRequest request,
            SettingRepository settings, Out<Delegation> delegation) throws InvalidSettingException {
        if (settings.find(sheet.id()).givenRoleOf(user) != Role.STEWARD) {
            throw new InvalidSettingException("Only a steward can delegate the steward role.");
        }
        String delegate = request.user() == null ? "" : request.user().trim();
        if (delegate.isEmpty()) {
            throw new InvalidSettingException("A user name is required.");
        }
        LocalDate from = date(request.from(), sheet.today());
        LocalDate to = date(request.to(), sheet.today());
        if (to.isBefore(from)) {
            throw new InvalidSettingException("The to-date cannot be before the from-date.");
        }
        delegation.set(new Delegation(sheet.id(), delegate, from, to, user));
    }

    private static LocalDate date(String value, LocalDate today) throws InvalidSettingException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return today;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidSettingException("A delegation's dates must be yyyy-mm-dd.");
        }
    }
}


public class ValidateRoleRequest {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody @Valid RoleRequest request,
            Out<UserRole> role) throws InvalidSettingException {
        String user = request.user() == null ? "" : request.user().trim();
        if (user.isEmpty()) {
            throw new InvalidSettingException("A user name is required.");
        }
        Role found = Role.of(request.role());
        if (found == null) {
            throw new InvalidSettingException("The role must be clerk, steward or viewer.");
        }
        role.set(new UserRole(sheetId, user, found));
    }
}


/**
 * Follows a claim's own record, when the claim was just settled, approved or re-settled (it ends SETTLED), with one
 * NOTIFY line per user watching its person, in the order they started watching. A clerk's settle that went PENDING
 * notifies no one.
 */
public class NotifyWatchers {
    public void audit(@Val Claim claim, @Val ClaimNumber number, PersonRepository people, WatchRepository watches,
            @RequestParam("user") String user, Audit audit) {
        if (claim.status() != ClaimStatus.SETTLED) {
            return;
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        String name = person == null ? "" : person.name();
        for (String watcher : watches.watchers(claim.sheetId(), claim.personId())) {
            audit.record("NOTIFY sheet=" + claim.sheetId() + " by=" + user + " user=" + watcher + " person=" + name
                    + Claim.auditNumber(number.value()));
        }
    }
}


/**
 * Closes a bulk settle once its claims are settled: one BATCH_SETTLED line with its batch number, how many claims are
 * in it (SETTLED or PENDING) and the frozen dues of those SETTLED added up. A bulk settle that took no batch number
 * (it settled nothing) writes nothing.
 */
public class AuditBatchSettled {

    /** The bulk settle's batch number (null: none). */
    public record BatchSettled(Integer batch) {
    }

    public void audit(@PathVariable("sheetId") String sheetId, @RequestParam("user") String user,
            @RequestBody BulkSettleRequest request, SettleBatchRepository batches, ClaimRepository claims, Audit audit,
            ObjectResponse<BatchSettled> response) {
        String token = request == null || request.batch() == null ? "" : request.batch().trim();
        Integer number = token.isEmpty() ? null : batches.numberOf(sheetId, token);
        if (number != null) {
            Map<Long, Integer> all = batches.batches(sheetId);
            List<Claim> inBatch = claims.findAll(sheetId).stream().filter((c) -> number.equals(all.get(c.id())))
                    .toList();
            BigDecimal total = inBatch.stream().filter((c) -> c.status() == ClaimStatus.SETTLED && c.due() != null)
                    .map(Claim::due).reduce(BigDecimal.ZERO, BigDecimal::add);
            audit.record("BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + number + " count="
                    + inBatch.size() + " total=" + total.setScale(2).toPlainString());
        }
        response.send(new BatchSettled(number));
    }
}
